useful_data['Clinical significance']=useful_data['Clinical significance'].map({"Pathogenic" : 1,"Likely pathogenic" : 1,"Pathogenic/Likely pathogenic": 1,"Benign":0,"Likely benign":0,"Benign/Likely benign":0 })

print(useful_data.head())

print(useful_data['Clinical significance'].unique())

print(useful_data['Clinical significance'].value_counts())

useful_data['position']= useful_data['variation'].str[1:-1]
useful_data['wt'] = useful_data['variation'].str[0]
useful_data['mut'] = useful_data['variation'].str[-1]

print(useful_data.head())

useful_data.drop(columns=['variation'],inplace=True)

useful_data = useful_data.rename(columns={'Clinical significance': 'pathogenicity'})

print(useful_data.head())

print(useful_data.isna().sum())

