useful_data = useful_data.merge(df[["Accession",'uniprot_id']],on="Accession",how="left")

print(useful_data.head())

print(useful_data)

print(useful_data['uniprot_id'].isna().sum())

useful_data['position'] = useful_data['position'].astype(int)

print(useful_data.head(

))

useful_data['sequence'] = useful_data['uniprot_id'].map(seq_dict)

print(useful_data.head())

