# useful_data['check'] = useful_data.apply(
#     lambda sample: sample['sequence'][sample['position']-1] == sample['wt'], axis=1
# )
useful_data['check'] = useful_data.apply(
    lambda sample: (
        sample['sequence'][sample['position'] - 1] == sample['wt']
        if isinstance(sample['sequence'], str) and sample['position'] <= len(sample['sequence'])
        else False
    ),
    axis=1
)

useful_data['check'].value_counts()

print(useful_data.head(

))

useful_data = useful_data[useful_data['check']==True]

print(useful_data.info())
print(useful_data.describe())

useful_data = useful_data.reset_index(drop=True)

print(useful_data.info())

useful_data.drop(columns=['check'],axis=1,inplace=True)

